#include <TM1637Display.h>

// Пины TM1637
#define CLK 6
#define DIO 7

TM1637Display display(CLK, DIO);

// Пины кнопок
const int btnPins[4] = {2, 3, 4, 5};

// Текущие значения разрядов
int val[4] = {1, 1, 0, 1}; // val[2] — индекс в массиве символов

// Набор символов для 3‑го разряда (индекс 2)
const char chars3[] = {'a','b','e','f','r','h','l','u','o','x'};
const int chars3Count = sizeof(chars3) / sizeof(chars3[0]);

// Для антидребезга и автоповтора
unsigned long lastDebounceTime[4] = {0};
unsigned long lastRepeatTime[4] = {0};
bool lastStableState[4] = {HIGH};   // стабильное состояние после антидребезга
bool currentStableState[4] = {HIGH};
bool isPressed[4] = {false};        // флаг, что кнопка сейчас считается нажатой

const unsigned long debounceDelay = 50;       // мс
const unsigned long repeatDelay = 400;         // мс (пауза перед автоповтором)
const unsigned long repeatInterval = 150;      // мс (частота автоповтора)

void setup() {
  for (int i = 0; i < 4; i++) {
    pinMode(btnPins[i], INPUT_PULLUP);
  }

  display.setBrightness(4); // яркость 0–7
  display.clear();
  updateDisplay();
}

void loop() {
  unsigned long currentMillis = millis();

  for (int i = 0; i < 4; i++) {
    int reading = digitalRead(btnPins[i]);

    // Антидребезг: обновляем стабильное состояние, если прошло debounceDelay
    if ((currentMillis - lastDebounceTime[i]) > debounceDelay) {
      if (reading != currentStableState[i]) {
        currentStableState[i] = reading;
        lastDebounceTime[i] = currentMillis; // сброс таймера антидребезга при изменении
      }
    }

    bool buttonIsPressed = (currentStableState[i] == LOW);

    if (buttonIsPressed) {
      if (!isPressed[i]) {
        // Первое срабатывание (однократный импульс)
        isPressed[i] = true;
        incrementValue(i);
        lastRepeatTime[i] = currentMillis;
      } else {
        // Автоповтор: пауза, потом быстрый повтор
        unsigned long elapsed = currentMillis - lastRepeatTime[i];
        if (elapsed >= repeatDelay) {
          incrementValue(i);
          lastRepeatTime[i] = currentMillis;
        } else if (elapsed >= repeatInterval && elapsed < repeatDelay) {
          // Можно добавить промежуточный шаг, если нужно
        }
      }
    } else {
      // Кнопка отпущена
      isPressed[i] = false;
    }
  }
}

void incrementValue(int i) {
  if (i == 2) {
    // 3‑й разряд: символы
    val[i]++;
    if (val[i] >= chars3Count) val[i] = 0;
  } else {
    // Остальные разряды: 1–8
    val[i]++;
    if (val[i] > 8) val[i] = 1;
  }
  updateDisplay();
}

void updateDisplay() {
  uint8_t data[4];

  // 1‑й разряд (индекс 0): цифра 1–8
  data[0] = display.encodeDigit(val[0]);

  // 2‑й разряд (индекс 1): цифра 1–8
  data[1] = display.encodeDigit(val[1]);

  // 3‑й разряд (индекс 2): символ из массива
  char c = chars3[val[2]];
  data[2] = charToSegment(c);

  // 4‑й разряд (индекс 3): цифра 1–8
  data[3] = display.encodeDigit(val[3]);

  display.setSegments(data, 4, 0);
}

uint8_t charToSegment(char c) {
  // Лучше использовать встроенные возможности библиотеки, если они есть.
  // Здесь оставляем ручной вариант, но с правильными кодами для common cathode.
  switch (c) {
    case 'a': return 0b01110111;
    case 'b': return 0b00010110;
    case 'e': return 0b01110001;
    case 'f': return 0b01110000;
    case 'r': return 0b00110000;
    case 'h': return 0b00110110;
    case 'l': return 0b00000110;
    case 'u': return 0b00010111;
    case 'o': return 0b00110111;
    case 'x': return 0b01110110;
    default:  return 0b00000000;
  }
}
